package fraymus.workspace;
import org.json.*;

/** Numeric-only report. Never includes a private camera bitmap. */
final class TabletopReport {
    static JSONObject data(JSONObject run,JSONObject understanding,JSONArray analyses){var rows=new JSONArray();for(Object raw:run.getJSONArray("trace")){var row=(JSONObject)raw;var e=row.getJSONObject("estimate");var t=row.getJSONObject("tracker");rows.put(new JSONObject().put("ordinal",row.getInt("ordinal")).put("seconds",row.getJSONObject("frame").getDouble("seconds")).put("imageSha256",row.getJSONObject("frame").getString("imageSha256")).put("positionM",e.getJSONArray("positionM")).put("predictedM",e.getJSONArray("predictedM")).put("velocityMps",e.getJSONArray("velocityMps")).put("radiusM",e.getDouble("radiusM")).put("sigmaM",e.getDouble("sigmaM")).put("accepted",e.getBoolean("accepted")).put("status",e.getString("status")).put("trackerStatus",t.getString("status")).put("score",t.getDouble("score")).put("margin",t.getDouble("margin")).put("referenceValid",row.getJSONObject("reference").getBoolean("valid")).put("processingMs",row.getDouble("processingMs")));}return new JSONObject().put("runId",run.getString("id")).put("target",run.getString("label")).put("nativeBinding",run.getJSONObject("nativeBinding")).put("geometry",run.getJSONObject("geometry")).put("check",run.getJSONObject("check")).put("status",run.getString("status")).put("rows",rows).put("understanding",understanding).put("analyses",analyses).put("scope","Actual private-camera numeric observations; camera pixels deliberately excluded. Human target label, planar projected centre, uncalibrated motion-model uncertainty, no native action authority.");}
    static JSONObject build(JSONObject run,JSONObject understanding,JSONArray analyses){var data=data(run,understanding,analyses);String html="""
        <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tabletop038 evidence</title><style>body{background:#101b26;color:#e4f2f6;font:16px/1.6 system-ui;padding:24px;margin:0;max-width:1100px}select,button{font:inherit;background:#24423e;color:inherit;padding:8px;border:1px solid #7ca298;border-radius:7px}canvas{width:100%;background:#152b35}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #48656b;white-space:nowrap;text-align:left}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
        <h1>Tabletop monitor · observed, predicted & verified</h1><p id="identity"></p><p id="scope"></p><p id="scale"></p><label>Metric<select id="metric"><option value="x">X / metres</option><option value="y">Y / metres</option><option value="speed">Speed / m/s</option><option value="radius">Model radius / metres</option><option value="score">Appearance match / not probability</option></select></label><canvas id="chart" width="1000" height="310"></canvas><p>Teal: measured estimate; orange: prediction-only. Every captured row remains present. Camera reference failure withholds measured updates. Report is a snapshot; check its receipt time before treating it as live.</p><div class="scroll"><table><thead><tr><th>Seconds</th><th>X m</th><th>Y m</th><th>m/s</th><th>Radius m</th><th>Match score</th><th>Reference</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div><details><summary>Grounded readout and independent checks</summary><pre id="facts"></pre></details><script id="evidence" type="application/json">__JSON__</script><script>
        const d=JSON.parse(document.getElementById('evidence').textContent),$=id=>document.getElementById(id);window.tabletopEvidence=d;$('identity').textContent='Run '+d.runId+' · world '+d.nativeBinding.worldId+' · '+d.status;$('scope').textContent=d.scope;$('scale').textContent='Independent tape: '+(d.check.expectedM*1000).toFixed(2)+' mm known, '+(d.check.measuredM*1000).toFixed(2)+' mm measured, error '+(d.check.absoluteErrorM*1000).toFixed(2)+' mm; '+(d.check.passed?'passed declared5mm gate':'rejected');$('facts').textContent=JSON.stringify({understanding:d.understanding,analyses:d.analyses},null,2);for(const r of d.rows){const tr=document.createElement('tr');for(const v of [r.seconds.toFixed(3),r.positionM[0].toFixed(4),r.positionM[1].toFixed(4),Math.hypot(...r.velocityMps).toFixed(4),r.radiusM.toFixed(4),r.score.toFixed(4),r.referenceValid?'stable':'changed/unverified',r.status]){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('rows').append(tr);}function draw(){const mode=$('metric').value,get=r=>mode==='x'?r.positionM[0]:mode==='y'?r.positionM[1]:mode==='speed'?Math.hypot(...r.velocityMps):mode==='radius'?r.radiusM:r.score,points=d.rows.map(r=>[r.seconds,get(r),r.accepted]);window.tabletopChart={mode,points};$('chart').dataset.proof=JSON.stringify(window.tabletopChart);const c=$('chart'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(!points.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);for(let i=0;i<points.length;i++){const p=points[i],x=55+920*(p[0]-xmin)/Math.max(.001,xmax-xmin),y=265-240*(p[1]-ymin)/Math.max(.0001,ymax-ymin);ctx.fillStyle=p[2]?'#78dfbf':'#e5ae6a';ctx.fillRect(x-2,y-2,4,4);}ctx.fillStyle='#dbeaf3';ctx.font='14px system-ui';ctx.fillText(ymax.toFixed(4),2,20);ctx.fillText(ymin.toFixed(4),2,270);ctx.fillText('Actual source seconds '+xmin.toFixed(2)+' → '+xmax.toFixed(2),55,300);}$('metric').onchange=draw;draw();</script></html>
        """.replace("__JSON__",data.toString().replace("<","\\u003c"));return new JSONObject().put("title","Tabletop observations · "+run.getString("label")).put("files",new JSONObject().put("index.html",html).put("tabletop-data.json",data.toString())).put("sources",new JSONArray().put(new JSONObject().put("runId",run.getString("id")).put("worldId",run.getJSONObject("nativeBinding").getString("worldId")).put("codeSha256",run.getString("codeSha256"))));}
}
